import React, { useState, useEffect } from 'react';
import { ChevronLeftIcon, ChevronRightIcon, CheckIcon } from '@heroicons/react/24/outline';
import apiService from '../services/api';
import { useNotification } from '../contexts/NotificationContext';
import DNSVerificationStep from './wizard/DNSVerificationStep';
import SPFConfigurationStep from './wizard/SPFConfigurationStep';
import DKIMConfigurationStep from './wizard/DKIMConfigurationStep';
import DMARCConfigurationStep from './wizard/DMARCConfigurationStep';
import CompletionStep from './wizard/CompletionStep';

const ConfigurationWizard = () => {
  const [currentStep, setCurrentStep] = useState(1);
  const [stepData, setStepData] = useState({});
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const { showNotification } = useNotification();

  const steps = [
    { id: 1, name: 'Verificación DNS', description: 'Verificar configuración DNS actual' },
    { id: 2, name: 'Configuración SPF', description: 'Configurar registro SPF' },
    { id: 3, name: 'Configuración DKIM', description: 'Configurar registro DKIM' },
    { id: 4, name: 'Configuración DMARC', description: 'Configurar política DMARC' },
    { id: 5, name: 'Finalización', description: 'Resumen y próximos pasos' }
  ];

  useEffect(() => {
    loadWizardProgress();
  }, []);

  const loadWizardProgress = async () => {
    try {
      setLoading(true);
      const progress = await apiService.getWizardProgress();
      if (progress) {
        setCurrentStep(progress.current_step || 1);
        setStepData(progress.step_data || {});
      }
    } catch (error) {
      console.error('Error loading wizard progress:', error);
      showNotification('Error al cargar el progreso del asistente', 'error');
    } finally {
      setLoading(false);
    }
  };

  const saveStepData = async (step, data) => {
    try {
      setSaving(true);
      await apiService.saveWizardStep(step, data);
      setStepData(prev => ({ ...prev, [step]: data }));
      showNotification('Progreso guardado correctamente', 'success');
    } catch (error) {
      console.error('Error saving step data:', error);
      showNotification('Error al guardar el progreso', 'error');
      throw error;
    } finally {
      setSaving(false);
    }
  };

  const nextStep = async () => {
    if (currentStep < steps.length) {
      const newStep = currentStep + 1;
      setCurrentStep(newStep);
      try {
        await apiService.saveWizardStep(newStep, stepData[newStep] || {});
      } catch (error) {
        console.error('Error updating step:', error);
      }
    }
  };

  const prevStep = () => {
    if (currentStep > 1) {
      setCurrentStep(currentStep - 1);
    }
  };

  const updateStepData = (data) => {
    setStepData(prev => ({ ...prev, [currentStep]: data }));
  };

  const resetWizard = async () => {
    try {
      await apiService.resetWizard();
      setCurrentStep(1);
      setStepData({});
      showNotification('Asistente reiniciado correctamente', 'success');
    } catch (error) {
      console.error('Error resetting wizard:', error);
      showNotification('Error al reiniciar el asistente', 'error');
    }
  };

  const renderStepContent = () => {
    const commonProps = {
      data: stepData[currentStep] || {},
      onDataChange: updateStepData,
      onNext: nextStep,
      onPrev: prevStep,
      onSave: (data) => saveStepData(currentStep, data),
      canGoBack: currentStep > 1,
      canGoNext: currentStep < steps.length,
      saving
    };

    switch (currentStep) {
      case 1:
        return <DNSVerificationStep {...commonProps} />;
      case 2:
        return <SPFConfigurationStep {...commonProps} />;
      case 3:
        return <DKIMConfigurationStep {...commonProps} />;
      case 4:
        return <DMARCConfigurationStep {...commonProps} />;
      case 5:
        return <CompletionStep {...commonProps} onReset={resetWizard} />;
      default:
        return <div>Paso no encontrado</div>;
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <div className="spinner h-12 w-12 mx-auto mb-4"></div>
          <p className="text-gray-600">Cargando asistente de configuración...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50">
      <div className="py-6">
        <div className="mx-auto max-w-4xl px-4 sm:px-6 lg:px-8">
          {/* Header */}
          <div className="mb-8">
            <h1 className="text-3xl font-bold text-gray-900">Asistente de Configuración DMARC</h1>
            <p className="mt-2 text-gray-600">
              Te guiaremos paso a paso para configurar la protección DMARC de tu dominio
            </p>
          </div>

          {/* Progress Bar */}
          <div className="mb-8">
            <div className="flex items-center justify-between mb-4">
              <span className="text-sm font-medium text-gray-700">
                Paso {currentStep} de {steps.length}
              </span>
              <span className="text-sm text-gray-500">
                {Math.round((currentStep / steps.length) * 100)}% completado
              </span>
            </div>
            <div className="w-full bg-gray-200 rounded-full h-2">
              <div
                className="bg-primary-600 h-2 rounded-full transition-all duration-300"
                style={{ width: `${(currentStep / steps.length) * 100}%` }}
              ></div>
            </div>
          </div>

          {/* Steps Navigation */}
          <div className="mb-8">
            <nav aria-label="Progress">
              <ol className="flex items-center">
                {steps.map((step, stepIdx) => (
                  <li key={step.id} className={`relative ${stepIdx !== steps.length - 1 ? 'pr-8 sm:pr-20' : ''}`}>
                    {stepIdx !== steps.length - 1 && (
                      <div className="absolute inset-0 flex items-center" aria-hidden="true">
                        <div className="h-0.5 w-full bg-gray-200" />
                      </div>
                    )}
                    <div className="relative flex items-center justify-center">
                      {step.id < currentStep ? (
                        <div className="h-8 w-8 rounded-full bg-primary-600 flex items-center justify-center">
                          <CheckIcon className="h-5 w-5 text-white" />
                        </div>
                      ) : step.id === currentStep ? (
                        <div className="h-8 w-8 rounded-full border-2 border-primary-600 bg-white flex items-center justify-center">
                          <span className="text-primary-600 font-medium text-sm">{step.id}</span>
                        </div>
                      ) : (
                        <div className="h-8 w-8 rounded-full border-2 border-gray-300 bg-white flex items-center justify-center">
                          <span className="text-gray-400 font-medium text-sm">{step.id}</span>
                        </div>
                      )}
                    </div>
                    <div className="mt-2 text-center">
                      <p className={`text-sm font-medium ${
                        step.id <= currentStep ? 'text-primary-600' : 'text-gray-500'
                      }`}>
                        {step.name}
                      </p>
                      <p className="text-xs text-gray-500">{step.description}</p>
                    </div>
                  </li>
                ))}
              </ol>
            </nav>
          </div>

          {/* Step Content */}
          <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6 mb-6">
            {renderStepContent()}
          </div>

          {/* Navigation Buttons */}
          <div className="flex justify-between">
            <button
              type="button"
              onClick={prevStep}
              disabled={currentStep === 1}
              className={`inline-flex items-center px-4 py-2 border border-gray-300 shadow-sm text-sm font-medium rounded-md ${
                currentStep === 1
                  ? 'text-gray-400 bg-gray-100 cursor-not-allowed'
                  : 'text-gray-700 bg-white hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary-500'
              }`}
            >
              <ChevronLeftIcon className="h-5 w-5 mr-2" />
              Anterior
            </button>

            <div className="flex space-x-3">
              <button
                type="button"
                onClick={resetWizard}
                className="inline-flex items-center px-4 py-2 border border-gray-300 shadow-sm text-sm font-medium rounded-md text-gray-700 bg-white hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary-500"
              >
                Reiniciar
              </button>

              {currentStep < steps.length ? (
                <button
                  type="button"
                  onClick={nextStep}
                  disabled={saving}
                  className="inline-flex items-center px-4 py-2 border border-transparent text-sm font-medium rounded-md shadow-sm text-white bg-primary-600 hover:bg-primary-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary-500 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {saving ? (
                    <>
                      <div className="spinner h-4 w-4 mr-2"></div>
                      Guardando...
                    </>
                  ) : (
                    <>
                      Siguiente
                      <ChevronRightIcon className="h-5 w-5 ml-2" />
                    </>
                  )}
                </button>
              ) : (
                <button
                  type="button"
                  onClick={() => window.location.href = '/'}
                  className="inline-flex items-center px-4 py-2 border border-transparent text-sm font-medium rounded-md shadow-sm text-white bg-green-600 hover:bg-green-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-green-500"
                >
                  Ir al Dashboard
                </button>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ConfigurationWizard;
